-- PostgreSQL; Study assumptions: the following is an illustrative schema.
CREATE TABLE restaurants (id bigint PRIMARY KEY);
CREATE TABLE customers (id bigint PRIMARY KEY);
CREATE TABLE orders (
  id bigint PRIMARY KEY,
  restaurant_id bigint NOT NULL REFERENCES restaurants(id),
  customer_id bigint NOT NULL REFERENCES customers(id),
  ordered_on date NOT NULL
);

SELECT r.id AS restaurant_id, COUNT(o.id) AS order_count
FROM restaurants r
LEFT JOIN orders o ON o.restaurant_id = r.id
                  AND o.ordered_on >= DATE '2026-10-01'
                  AND o.ordered_on < DATE '2026-11-01'
GROUP BY r.id
ORDER BY r.id;

-- PostgreSQL; Study assumptions: date_text contains valid DD/MM/YYYY or NULL.
SELECT id, TO_DATE(date_text, 'FXDD/MM/YYYY') AS parsed_date
FROM imported
ORDER BY id;

